<script setup>
import { reactive, ref } from 'vue'
import AccountAvatar from './AccountAvatar.vue'
import {prepareAvatar} from '../services/avatar.js'
import {isStaticDemo} from '../runtime.js'
import { account, saveProfile, updatePassword, savePreferences } from '../domain/account.js'
const props=defineProps({mode:String}),emit=defineEmits(['done','message','close'])
const user=account.user,profile=reactive({avatar:user.avatar||'',displayName:user.displayName,email:user.email||'',phone:user.phone||'',bio:user.bio||''}),password=reactive({current:'',next:'',confirm:''}),preferences=reactive({...user.preferences}),error=ref(''),busy=ref(false)
const avatarInput=ref(null),avatarBusy=ref(false)
async function chooseAvatar(event){
 const file=event.target.files?.[0];event.target.value='';if(!file||busy.value||avatarBusy.value)return
 error.value='';avatarBusy.value=true
 try{profile.avatar=await prepareAvatar(file)}catch(e){error.value=e.message}finally{avatarBusy.value=false}
}
async function save(){if(avatarBusy.value||busy.value)return;error.value='';busy.value=true;try{if(props.mode==='profile')await saveProfile(profile);if(props.mode==='password'){if(password.next!==password.confirm)throw Error('两次输入的新密码不一致。');await updatePassword(password.current,password.next);password.current='';password.next='';password.confirm='';emit('close');return}if(props.mode==='preferences')await savePreferences(preferences);emit('done',props.mode==='preferences'?'显示设置已保存，将用于下次登录。':'个人资料已保存。')}catch(e){error.value=e.message}finally{busy.value=false}}
</script>
<template><form class="account-form" @submit.prevent="save"><p v-if="error" class="form-error" role="alert">{{error}}</p><template v-if="mode==='profile'"><div class="account-summary"><div class="avatar-controls"><input ref="avatarInput" class="avatar-file" type="file" accept="image/jpeg,image/png,image/webp" aria-label="上传头像图片" :disabled="busy||avatarBusy" @change="chooseAvatar"/><button class="avatar-preview" type="button" aria-label="更换头像" :disabled="busy||avatarBusy" @click="avatarInput?.click()"><AccountAvatar class="profile-avatar-large" :src="profile.avatar" :name="profile.displayName"/></button><div class="avatar-actions"><button class="text-button" type="button" :disabled="busy||avatarBusy" @click="avatarInput?.click()">{{avatarBusy?'正在处理…':'更换头像'}}</button><button v-if="profile.avatar" class="text-button" type="button" :disabled="busy||avatarBusy" @click="profile.avatar=''">恢复默认</button></div></div><div><strong>{{user.displayName}}</strong><p>{{user.username}} · 管理员</p></div></div><p class="avatar-hint">支持 JPG、PNG、WebP，最大5MB；自动裁剪为方形，保存后生效。</p><div class="account-field-grid"><label>登录账号<input :value="user.username" readonly/></label><label>角色<input value="管理员" readonly/></label><label class="full-field">显示名称 <b>*</b><input v-model="profile.displayName" required maxlength="60" autocomplete="name"/></label><label>邮箱<input v-model="profile.email" type="email" maxlength="160" autocomplete="email" placeholder="选填"/></label><label>联系电话<input v-model="profile.phone" maxlength="24" autocomplete="tel" placeholder="选填"/></label><label class="full-field">个人说明<textarea v-model="profile.bio" rows="3" maxlength="300"/></label></div><p class="form-hint">{{isStaticDemo?'公开演示资料仅保存在当前浏览器，不会上传服务器，请使用虚构信息。':'只修改当前登录账号资料，登录账号和管理员角色不可在此修改。'}}</p></template><template v-else-if="mode==='password'"><p class="password-notice">修改后所有旧会话会失效，需要重新登录。</p><label>原密码<input v-model="password.current" type="password" required autocomplete="current-password" maxlength="64"/></label><label>新密码<input v-model="password.next" type="password" required autocomplete="new-password" minlength="10" maxlength="64"/></label><label>确认新密码<input v-model="password.confirm" type="password" required autocomplete="new-password" minlength="10" maxlength="64"/></label><p class="form-hint">10～64 个字符，须包含字母和数字，可使用符号；不能与原密码相同。</p></template><template v-else><label>全局字号<select v-model="preferences.fontSize"><option value="normal">标准字号</option><option value="large">较大字号</option><option value="xlarge">大字号</option></select></label><label>表格密度<select v-model="preferences.density"><option value="comfortable">标准行距</option><option value="compact">紧凑行距</option></select></label><p class="form-hint">{{isStaticDemo?'字号与密度仅保存在当前浏览器。':'字号应用于导航、表单、表格、卡片和图表，并随当前账号保存。'}}</p></template><footer class="account-form-actions"><button class="outline-button" type="button" :disabled="busy" @click="emit('close')">取消</button><button class="soft-button active" :disabled="busy||avatarBusy" type="submit">{{busy?'正在保存…':mode==='password'?'确认修改密码':'保存'}}</button></footer></form></template>

<style scoped>.avatar-controls{display:flex;flex-direction:column;align-items:center;gap:8px;flex-shrink:0}.avatar-file{display:none}.avatar-preview{border:0;padding:0;background:none;cursor:pointer;border-radius:50%;line-height:0}.avatar-preview:focus-visible{outline:2px solid #8c7ee4;outline-offset:4px}.avatar-actions{display:flex;gap:10px;flex-wrap:wrap;justify-content:center}.avatar-actions button{font-size:12px}.avatar-hint{font-size:12px;color:#a39bb1;line-height:1.8;margin:0 0 18px}.avatar-preview:disabled{opacity:.6;cursor:default}</style>
